#!/usr/bin/env python3
"""Build an offline, single-file publishing page from metadata and approved media."""
import argparse, base64, html, json, hashlib
from pathlib import Path

def make_page(meta, video, thumb):
    esc=html.escape
    fields=''.join(f'<section class="field"><div class="fieldhead"><label for="f{i}">{esc(k)}</label><button type="button" data-copy="f{i}">Copy</button></div><textarea id="f{i}" readonly rows="{min(18,max(1,v.count(chr(10))+1))}">{esc(v)}</textarea></section>' for i,(k,v) in enumerate(meta['fields'].items()))
    checks=''.join(f'<label class="check"><input type="checkbox" {"checked" if c["done"] else ""}> {esc(c["label"])}</label>' for c in meta['checklist'])
    assets={key:{'name':p.name,'mime':mime,'data':base64.b64encode(p.read_bytes()).decode(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for key,p,mime in [('video',video,'video/mp4'),('thumbnail',thumb,'image/png')]}
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'''+esc(meta['id'])+''' — Bharat Mode publishing</title><style>
:root{color-scheme:light;--ivory:#fff7eb;--navy:#283039;--teal:#117a7a;--saffron:#e8752e}*{box-sizing:border-box}body{margin:0;background:var(--ivory);color:var(--navy);font:16px/1.5 system-ui,sans-serif}header{background:#0b1018;color:var(--ivory);padding:24px max(24px,calc((100% - 1100px)/2));border-bottom:5px solid var(--saffron)}header p{margin:4px 0;color:#d2e1df}h1{font-size:clamp(24px,4vw,36px);line-height:1.2;margin:6px 0}h2{font-size:20px}main{max-width:1140px;margin:auto;padding:24px;display:grid;grid-template-columns:300px 1fr;gap:24px}aside,article{min-width:0}section,aside{background:#fffdf8;border:1px solid #dfd8cc;border-radius:12px;padding:16px;margin-bottom:14px}aside{align-self:start}img{display:block;width:100%;max-width:280px;margin:0 auto 14px;border-radius:7px}button{font:inherit;font-weight:650;border:1px solid #117a7a;background:#117a7a;color:white;border-radius:6px;padding:8px 14px;cursor:pointer}button:focus-visible,textarea:focus-visible,input:focus-visible{outline:3px solid #e8752e;outline-offset:2px}aside button{width:100%;margin:6px 0}small{display:block;overflow-wrap:anywhere;color:#56616a}.fieldhead{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:8px;font-weight:700}textarea{font:inherit;width:100%;resize:vertical;background:#fff7eb;color:#283039;border:1px solid #e4d9cb;border-radius:6px;padding:10px;min-height:44px;overflow-wrap:anywhere}.check{display:flex;align-items:baseline;gap:8px;margin:10px 0}#status{min-height:1.5em;font-size:14px;color:#117a7a}footer{padding:16px;max-width:1100px;margin:auto;color:#56616a}@media(max-width:720px){main{grid-template-columns:1fr;padding:14px}aside{max-width:none}img{max-width:230px}}
</style></head><body><header><strong>BHARAT MODE · PUBLISHING DESK</strong><h1>'''+esc(meta['id']+' — '+meta['name'])+'''</h1><p>Creative assets approved · Not published · Upload settings proposed</p></header><main><aside><h2>Final assets</h2><img alt="Approved custom thumbnail" src="data:image/png;base64,'''+assets['thumbnail']['data']+'''"><button data-download="thumbnail">Download thumbnail PNG</button><small>'''+esc(thumb.name)+'''</small><button data-download="video">Download final MP4</button><small>'''+esc(video.name)+'''</small><p>Open this HTML file in your browser. Both files are embedded; no external server or separate download is required.</p><div id="status" role="status" aria-live="polite"></div></aside><article>'''+fields+'''<section><h2>Publication checklist</h2>'''+checks+'''<p><small>Checks are local to this page session. Checking a box does not upload anything or update the project registry.</small></p></section></article></main><footer>Private release page · No external requests · No automatic upload or publication</footer><script type="application/json" id="assets">'''+json.dumps(assets,separators=(',',':'))+'''</script><script>
const status=document.getElementById('status');
document.querySelectorAll('[data-copy]').forEach(btn=>btn.addEventListener('click',async()=>{const field=document.getElementById(btn.dataset.copy);let ok=false;try{if(navigator.clipboard&&navigator.clipboard.writeText){await navigator.clipboard.writeText(field.value);ok=true;}}catch(e){}if(!ok){field.focus();field.select();try{ok=document.execCommand('copy');}catch(e){}}btn.textContent=ok?'Copied':'Select and copy';status.textContent=ok?'Copied to clipboard.':'Clipboard blocked. Text selected; press Ctrl+C or Cmd+C.';}));
let assets;document.querySelectorAll('[data-download]').forEach(btn=>btn.addEventListener('click',()=>{try{assets=assets||JSON.parse(document.getElementById('assets').textContent);const a=assets[btn.dataset.download];const raw=atob(a.data),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);const url=URL.createObjectURL(new Blob([bytes],{type:a.mime}));const link=document.createElement('a');link.href=url;link.download=a.name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);status.textContent='Download requested: '+a.name;}catch(e){status.textContent='Download failed. Use the direct file link from chat.';}}));
</script></body></html>'''

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--metadata',type=Path,required=True);p.add_argument('--video',type=Path,required=True);p.add_argument('--thumbnail',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();a.output.write_text(make_page(json.loads(a.metadata.read_text()),a.video,a.thumbnail),encoding='utf-8')